// GP1 - Grouping/reimbursement - Visit
// These fields are used in grouping and reimbursement for CMS APCs. Please refer to the "Outpatient Prospective Payment System Final Rule" ("OPPS Final Rule") issued by CMS.
//
// The GP1 segment is specific to the US and may not be implemented in non-US systems.
type GP1 struct {
	TypeOfBillCode              *CWE  `hl7:"1,required"`
	RevenueCode                 []CWE `hl7:"2"`
	OverallClaimDispositionCode *CWE  `hl7:"3"`
	OceEditsPerVisitCode        []CWE `hl7:"4"`
	OutlierCost                 *CP   `hl7:"5"`
}

func NewGP1() *GP1 {
	return &GP1{}
}

func (s *GP1) Validate() error {

	if s.TypeOfBillCode == nil {
		return fmt.Errorf("GP1.TypeOfBillCode is required")
	}
	if s.TypeOfBillCode != nil {
		if err := s.TypeOfBillCode.Validate(); err != nil {
			return fmt.Errorf("GP1.TypeOfBillCode: %w", err)
		}
	}

	for _, item := range s.RevenueCode {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("GP1.RevenueCode: %w", err)
		}
	}

	if s.OverallClaimDispositionCode != nil {
		if err := s.OverallClaimDispositionCode.Validate(); err != nil {
			return fmt.Errorf("GP1.OverallClaimDispositionCode: %w", err)
		}
	}

	for _, item := range s.OceEditsPerVisitCode {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("GP1.OceEditsPerVisitCode: %w", err)
		}
	}

	if s.OutlierCost != nil {
		if err := s.OutlierCost.Validate(); err != nil {
			return fmt.Errorf("GP1.OutlierCost: %w", err)
		}
	}
	return nil
}

