// PEO - Product Experience Observation
// Details related to a particular clinical experience or event are embodied in the PEO segment. This segment can be used to characterize an event which might be attributed to a product to which the patient was exposed. Products with a possible causal relationship to the observed experience are described in the following PCR (possible causal relationship) segments. The message format was designed to be robust and includes many optional elements which may not be required for a particular regulatory purpose but allow a complete representation of the drug experience if needed.
//
// A PEX message can contain multiple PEO segments if the patient experienced more than one event but must contain at least one PEO segment.
type PEO struct {
	EventIdentifiersUsed                  []CWE `hl7:"1"`
	EventSymptomDiagnosisCode             []CWE `hl7:"2"`
	EventOnsetDateTime                    *DTM  `hl7:"3,required"`
	EventExacerbationDateTime             *DTM  `hl7:"4"`
	EventImprovedDateTime                 *DTM  `hl7:"5"`
	EventEndedDataTime                    *DTM  `hl7:"6"`
	EventLocationOccurredAddress          []XAD `hl7:"7"`
	EventQualification                    []ID  `hl7:"8"`
	EventSerious                          *ID   `hl7:"9"`
	EventExpected                         *ID   `hl7:"10"`
	EventOutcome                          []ID  `hl7:"11"`
	PatientOutcome                        *ID   `hl7:"12"`
	EventDescriptionFromOthers            []FT  `hl7:"13"`
	EventDescriptionFromOriginalReporter  []FT  `hl7:"14"`
	EventDescriptionFromPatient           []FT  `hl7:"15"`
	EventDescriptionFromPractitioner      []FT  `hl7:"16"`
	EventDescriptionFromAutopsy           []FT  `hl7:"17"`
	CauseOfDeath                          []CWE `hl7:"18"`
	PrimaryObserverName                   []XPN `hl7:"19"`
	PrimaryObserverAddress                []XAD `hl7:"20"`
	PrimaryObserverTelephone              []XTN `hl7:"21"`
	PrimaryObserverSQualification         *ID   `hl7:"22"`
	ConfirmationProvidedBy                *ID   `hl7:"23"`
	PrimaryObserverAwareDateTime          *DTM  `hl7:"24"`
	PrimaryObserverSIdentityMayBeDivulged *ID   `hl7:"25"`
}

